describe('User Profile Data Export', () => {
    beforeEach(() => {
        cy.visit('/user-profile');
        cy.login('testuser', 'password123'); // Assuming a login function exists
    });

    it('should successfully export personal data as a JSON file', () => {
        cy.get('button#export-data').click();
        cy.wait(2000); // Wait for the export to complete
        cy.readFile('cypress/downloads/user-data.json').should('exist');
        cy.readFile('cypress/downloads/user-data.json').then((data) => {
            expect(data).to.have.property('name', 'Test User');
            expect(data).to.have.property('email', 'testuser@example.com');
        });
    });

    it('should handle export failure gracefully', () => {
        cy.intercept('GET', '/api/export-data', { statusCode: 500 }).as('exportDataFailure');
        cy.get('button#export-data').click();
        cy.wait('@exportDataFailure');
        cy.get('.error-message').should('be.visible').and('contain', 'Failed to export data. Please try again later.');
    });
});
